-- Bardstown Bourbon Company import (bourbon.bardstown_bourbon), applied 2026-09-24 via the Supabase MCP. No hand steps.
-- Scope: the Origin Series (house evergreen line) + Distillery Reserve's three named permanent finishes (Cascadia, Cathedral French Oak, Hokkaido Mizunara) + the current Discovery Series vintage.
-- The large Collaborative Series (Founders KBS, Goose Island, Silver Oak, Amrut, Mars, and ~15 more one-off brewery/winery barrel swaps) and the single-barrel program pages (no fixed proof) were not crawled.
-- Also fixed catalog/bourbon/normalize.py:spirit_type(), a real bug: a maker whose own name contains "Bourbon" (Bardstown Bourbon Company) was misclassifying its own rye as spirit_type=bourbon, because the guard checked the combined class+name text instead of the label's class statement alone. Verified no regression across all 13 previously-applied sources.

update cellar.products set proof = 112.8, producer = coalesce(producer, 'Bardstown Bourbon Company'), producer_id = coalesce(producer_id, 'c31beccf-57f2-480b-bb3f-7b5dc9d773af'::uuid), source = 'maker', source_url = 'https://www.bardstownbourbon.com/products/discovery-2026/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '724c339c-fa7c-4050-bfd8-29dbd450b7a5' and facts_verified_at is null;
update cellar.products set proof = 96.0, age_years = 6.0, age_label = '6 yr', nas = false, mash_style = 'high_rye', name = 'Bardstown Bourbon Company Origin Series Bourbon', expression = 'Origin Series Bourbon', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Bardstown Bourbon Company Fusion Series')) a), producer = coalesce(producer, 'Bardstown Bourbon Company'), producer_id = coalesce(producer_id, 'c31beccf-57f2-480b-bb3f-7b5dc9d773af'::uuid), source = 'maker', source_url = 'https://www.bardstownbourbon.com/products/origin-series-bourbon/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'b7f0d81b-16f4-4436-b9fb-f48ce284e43b' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('724c339c-fa7c-4050-bfd8-29dbd450b7a5', 'b7f0d81b-16f4-4436-b9fb-f48ce284e43b');
insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://www.bardstownbourbon.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
