,"al":"6 yr","nas":false,"et":"standard","ms":"rye","mb":"Rye 95% / Malted Barley 5%","st":"rye","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://www.bardstownbourbon.com/wp-content/uploads/2022/12/BBCo_Core_Line_750ml_-Rye_Whiskey-scaled-1.png","u":"https://www.bardstownbourbon.com/products/origin-series-rye/","pr":"Bardstown Bourbon Company","mk":"c31beccf-57f2-480b-bb3f-7b5dc9d773af"},{"n":"Bardstown Bourbon Company Origin Series Wheated Bottled in Bond","rar":"shelf","f":"Bardstown Bourbon Company","x":"Origin Series Wheated Bottled in Bond","p":100.0,"ay":6.0,"al":"6 yr","nas":false,"et":"standard","ms":"wheated","mb":"Corn 68% / Wheat 20% / Malted Barley 12%","st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://www.bardstownbourbon.com/wp-content/uploads/2022/12/BBCo_Core_Line_750ml_-BiB_Bourbon-scaled-1.png","u":"https://www.bardstownbourbon.com/products/origin-series-wheated-bottled-in-bond/","pr":"Bardstown Bourbon Company","mk":"c31beccf-57f2-480b-bb3f-7b5dc9d773af"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');